def compile_library(value, law_material):
    validate(value['program'])
    functions = {f.name: f for f in ast.parse(value['program']).body}
    units, heads = {}, set()
    for unit in value['units']:
        unit = dict(unit)
        if not re.fullmatch(r'\d+(?:\([A-Za-z0-9]+\))*', unit['clause']):
